#!/usr/bin/env python3
"""Deterministically compose Cambium's selected-profile vocabulary artifact.

This is a one-time Stage 3 generator. It is intentionally kept outside the
repository; its complete source and hash are embedded in the build receipt.
"""

from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import re
import subprocess
import sys
from typing import Any


BATCH_ID = "B16-TOOLS"
SOURCE_HEAD = "44d4c22"
SOURCE_COMMIT = "44d4c22f4acf2622e999053163b2f4fcd27cfd77"
KERNEL_PATH = "kernel/08 Metadata and Status/vocabulary-base.yaml"
PROFILE_PATH = "profiles/agent-atlas/vocabulary-extensions.yaml"
OUTPUT_PATH = "Tools/vocab.yaml"
RECEIPT_PATH = "docs/vocab_build_receipt.json"
COMMAND = (
    "PYTHONDONTWRITEBYTECODE=1 python3 /tmp/cambium_vocab_build.py "
    "--root . --output Tools/vocab.yaml "
    "--receipt docs/vocab_build_receipt.json"
)
CHECK_COMMAND = [
    "python3",
    "Tools/check_vocab.py",
    ".",
    "--vocab",
    "Tools/vocab.yaml",
]
ACTIVE_CHECKS = [
    {
        "scope": "kernel",
        "command": CHECK_COMMAND + ["--scope", "kernel"],
        "expected_counts": {
            "files": 93,
            "no_frontmatter": 93,
            "unparseable": 0,
            "unknown_value": 0,
            "missing_field": 0,
            "ok_values": 0,
        },
    },
    {
        "scope": "profiles",
        "command": CHECK_COMMAND + ["--scope", "profiles"],
        "expected_counts": {
            "files": 23,
            "no_frontmatter": 23,
            "unparseable": 0,
            "unknown_value": 0,
            "missing_field": 0,
            "ok_values": 0,
        },
    },
]
EXPECTED_INPUTS = {
    KERNEL_PATH: {
        "bytes": 2794,
        "sha256": "4b952bbd7f7568f3e022d8956547a345b659171c26b01eebd66333e6c412716b",
    },
    PROFILE_PATH: {
        "bytes": 1393,
        "sha256": "1b2b98a1ccb4f1c84784e685f8fc7bf37a1512dfaa76f82f9452ed331f8908c0",
    },
}
EXPECTED_FIELD_COUNTS = {
    "type": 20,
    "domain": 11,
    "scope": 5,
    "level": 3,
    "depth": 3,
    "priority": 3,
    "authoring_status": 4,
    "learning_status": 4,
    "coverage_disposition": 4,
    "evidence_maturity": 6,
    "volatility": 3,
    "lifecycle": 3,
    "interview_status": 6,
}
EXPECTED_OUTPUT = {
    "bytes": 4238,
    "lines": 156,
    "sha256": "204bb46e1967822f5cff90460216bc06977edb23d1c339093ee148bb8f79f8f6",
}
EXPECTED_CHECK_COUNTS = {
    "files": 139,
    "no_frontmatter": 128,
    "unparseable": 0,
    "unknown_value": 0,
    "missing_field": 132,
    "ok_values": 11,
}
ROOT_KEY_ORDER = [
    "schema_version",
    "profile_id",
    "composition_policy",
    "compiled_from",
    "frontmatter_extensions",
    "fields",
    "review_intervals_days",
    "volatility_defaults",
    "task_state",
]
HEADER = [
    "# Deterministically generated; do not edit directly.",
    "# Rebuild instructions and provenance: docs/vocab_build_receipt.json",
    "",
]


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def read_input(root: Path, relative_path: str) -> tuple[str, bytes]:
    raw = (root / relative_path).read_bytes()
    expected = EXPECTED_INPUTS[relative_path]
    actual = {"bytes": len(raw), "sha256": sha256_bytes(raw)}
    if actual != expected:
        raise RuntimeError(
            f"input drift for {relative_path}: expected {expected}, got {actual}"
        )
    return raw.decode("utf-8"), raw


def load_kblib(root: Path) -> Any:
    module_path = root / "Tools/kblib.py"
    spec = importlib.util.spec_from_file_location("cambium_kblib", module_path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load {module_path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def assert_unique(values: list[Any], label: str) -> None:
    seen: list[Any] = []
    for value in values:
        if value in seen:
            raise RuntimeError(f"duplicate source value in {label}: {value!r}")
        seen.append(value)


def compose(base: dict[str, Any], profile: dict[str, Any]) -> dict[str, Any]:
    if base.get("schema_version") != 1 or profile.get("schema_version") != 1:
        raise RuntimeError("both inputs must use schema_version 1")
    if profile.get("profile_id") != "agent-atlas":
        raise RuntimeError("selected profile must be agent-atlas")
    if profile.get("extends") != KERNEL_PATH:
        raise RuntimeError("profile extends path does not match the kernel input")
    if base.get("composition_policy") != "append-only-profile-extensions":
        raise RuntimeError("unexpected kernel composition policy")
    if profile.get("composition_policy") != "append-only":
        raise RuntimeError("unexpected profile composition policy")

    base_fields = base.get("fields")
    profile_fields = profile.get("fields")
    if not isinstance(base_fields, dict) or not isinstance(profile_fields, dict):
        raise RuntimeError("both inputs must contain a fields mapping")

    fields: dict[str, Any] = {}
    for name, base_spec in base_fields.items():
        if not isinstance(base_spec, dict):
            raise RuntimeError(f"kernel field {name} is not a mapping")
        if list(base_spec) != ["owner", "values"]:
            raise RuntimeError(f"unexpected kernel field schema for {name}")
        base_values = list(base_spec.get("values") or [])
        assert_unique(base_values, f"kernel fields.{name}.values")

        merged_spec: dict[str, Any] = {"owner": base_spec["owner"]}
        extension = profile_fields.get(name)
        if extension is not None:
            if not isinstance(extension, dict) or list(extension) != ["owner", "values"]:
                raise RuntimeError(f"profile may only append owner+values to {name}")
            extension_values = list(extension.get("values") or [])
            assert_unique(extension_values, f"profile fields.{name}.values")
            merged_spec["extension_owner"] = extension["owner"]
            for value in extension_values:
                if value not in base_values:
                    base_values.append(value)
        merged_spec["values"] = base_values
        fields[name] = merged_spec

    for name, profile_spec in profile_fields.items():
        if name in fields:
            continue
        if not isinstance(profile_spec, dict):
            raise RuntimeError(f"profile-only field {name} is not a mapping")
        if list(profile_spec) != ["owner", "role", "values"]:
            raise RuntimeError(f"unexpected profile-only field schema for {name}")
        values = list(profile_spec.get("values") or [])
        assert_unique(values, f"profile fields.{name}.values")
        fields[name] = {
            "owner": profile_spec["owner"],
            "role": profile_spec["role"],
            "values": values,
        }

    output = {
        "schema_version": base["schema_version"],
        "profile_id": profile["profile_id"],
        "composition_policy": base["composition_policy"],
        "compiled_from": {"kernel": KERNEL_PATH, "profile": PROFILE_PATH},
        "frontmatter_extensions": profile["frontmatter_extensions"],
        "fields": fields,
        "review_intervals_days": base["review_intervals_days"],
        "volatility_defaults": profile["volatility_defaults"],
        "task_state": base["task_state"],
    }
    if list(output) != ROOT_KEY_ORDER:
        raise RuntimeError("root key order drift")
    return output


def emit_scalar(value: Any) -> str:
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    raise TypeError(f"unsupported scalar: {value!r}")


def emit_map(mapping: dict[str, Any], indent: int = 0) -> list[str]:
    lines: list[str] = []
    prefix = " " * indent
    for key, value in mapping.items():
        if not re.fullmatch(r"[A-Za-z0-9_-]+", key):
            raise RuntimeError(f"unsupported YAML key: {key!r}")
        if isinstance(value, dict):
            lines.append(f"{prefix}{key}:")
            lines.extend(emit_map(value, indent + 2))
        elif isinstance(value, list):
            if not value:
                lines.append(f"{prefix}{key}: []")
            else:
                lines.append(f"{prefix}{key}:")
                for item in value:
                    if isinstance(item, (dict, list)):
                        raise RuntimeError("nested containers in lists are unsupported")
                    lines.append(f"{prefix}  - {emit_scalar(item)}")
        else:
            rendered = emit_scalar(value)
            lines.append(f"{prefix}{key}:" + (f" {rendered}" if rendered else ""))
    return lines


def render(output: dict[str, Any]) -> str:
    return "\n".join(HEADER + emit_map(output)) + "\n"


def parse_check_counts(stdout: str) -> dict[str, int]:
    patterns = {
        "files": r"check_vocab: 扫描 (\d+) 个文件",
        "no_frontmatter": r"无 frontmatter=(\d+)",
        "unparseable": r"不可解析=(\d+)",
        "unknown_value": r"非法取值\(fail\)=(\d+)",
        "missing_field": r"缺字段\(candidate\)=(\d+)",
        "ok_values": r"合法取值=(\d+)",
    }
    counts: dict[str, int] = {}
    for key, pattern in patterns.items():
        match = re.search(pattern, stdout)
        if not match:
            raise RuntimeError(f"cannot parse check_vocab count {key}")
        counts[key] = int(match.group(1))
    return counts


def run_vocab_check(
    root: Path,
    command: list[str],
    expected_counts: dict[str, int],
) -> dict[str, Any]:
    check_env = os.environ.copy()
    check_env["PYTHONDONTWRITEBYTECODE"] = "1"
    completed = subprocess.run(
        command,
        cwd=root,
        env=check_env,
        text=True,
        capture_output=True,
    )
    counts = parse_check_counts(completed.stdout)
    if completed.returncode != 2 or counts != expected_counts:
        raise RuntimeError(
            "unexpected check_vocab result: "
            f"command={' '.join(command)!r} exit={completed.returncode} "
            f"counts={counts}\nstdout:\n{completed.stdout}\n"
            f"stderr:\n{completed.stderr}"
        )
    return {
        "command": " ".join(command),
        "exit_code": completed.returncode,
        "result": "no-fail-with-candidates",
        "counts": counts,
        "raw_stdout": completed.stdout,
        "raw_stderr": completed.stderr,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--receipt", required=True)
    args = parser.parse_args()

    root = Path(args.root).resolve()
    if args.output != OUTPUT_PATH or args.receipt != RECEIPT_PATH:
        raise RuntimeError("output and receipt paths are fixed by the B16 contract")
    actual_head = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=root,
        check=True,
        text=True,
        capture_output=True,
    ).stdout.strip()
    if actual_head != SOURCE_COMMIT:
        raise RuntimeError(f"source HEAD drift: {actual_head}")

    kblib = load_kblib(root)
    kernel_text, kernel_raw = read_input(root, KERNEL_PATH)
    profile_text, profile_raw = read_input(root, PROFILE_PATH)
    base = kblib.parse_yaml_subset(kernel_text)
    profile = kblib.parse_yaml_subset(profile_text)
    output = compose(base, profile)
    rendered = render(output)
    rendered_raw = rendered.encode("utf-8")
    output_metrics = {
        "bytes": len(rendered_raw),
        "lines": len(rendered.splitlines()),
        "sha256": sha256_bytes(rendered_raw),
    }
    if output_metrics != EXPECTED_OUTPUT:
        raise RuntimeError(
            f"rendered output drift: expected {EXPECTED_OUTPUT}, got {output_metrics}"
        )
    if kblib.parse_yaml_subset(rendered) != output:
        raise RuntimeError("kblib round-trip mismatch")

    field_counts = {
        name: len(spec.get("values") or [])
        for name, spec in output["fields"].items()
    }
    if field_counts != EXPECTED_FIELD_COUNTS:
        raise RuntimeError(f"field counts drift: {field_counts}")
    value_count = sum(field_counts.values())
    if len(field_counts) != 13 or value_count != 75:
        raise RuntimeError("semantic aggregate counts drift")

    output_file = root / args.output
    output_file.write_bytes(rendered_raw)

    broad_check = run_vocab_check(root, CHECK_COMMAND, EXPECTED_CHECK_COUNTS)
    active_checks = [
        {
            "scope": spec["scope"],
            **run_vocab_check(root, spec["command"], spec["expected_counts"]),
        }
        for spec in ACTIVE_CHECKS
    ]
    active_aggregate = {
        "files": sum(item["counts"]["files"] for item in active_checks),
        "candidate_files": sum(
            item["counts"]["no_frontmatter"] for item in active_checks
        ),
        "unknown_value": sum(
            item["counts"]["unknown_value"] for item in active_checks
        ),
    }
    if active_aggregate != {
        "files": 116,
        "candidate_files": 116,
        "unknown_value": 0,
    }:
        raise RuntimeError(f"active corpus aggregate drift: {active_aggregate}")

    generator_path = Path(__file__)
    if str(generator_path) != "/tmp/cambium_vocab_build.py":
        raise RuntimeError(f"generator invocation path drift: {generator_path}")
    generator_source = generator_path.read_text(encoding="utf-8")
    generator_raw = generator_source.encode("utf-8")
    receipt = {
        "receipt_version": 1,
        "batch_id": BATCH_ID,
        "source_head": SOURCE_HEAD,
        "source_commit": SOURCE_COMMIT,
        "artifact": OUTPUT_PATH,
        "generator": {
            "kind": "one-time-python",
            "persistent_compiler_committed": False,
            "path": str(generator_path),
            "sha256": sha256_bytes(generator_raw),
            "bytes": len(generator_raw),
            "workdir": str(root),
            "command": COMMAND,
            "source": generator_source,
        },
        "inputs": [
            {
                "order": 1,
                "role": "kernel-base",
                "path": KERNEL_PATH,
                "sha256": sha256_bytes(kernel_raw),
                "bytes": len(kernel_raw),
            },
            {
                "order": 2,
                "role": "selected-profile-extension",
                "path": PROFILE_PATH,
                "sha256": sha256_bytes(profile_raw),
                "bytes": len(profile_raw),
            },
        ],
        "preconditions": {
            "schema_version": 1,
            "profile_id": "agent-atlas",
            "extends": KERNEL_PATH,
            "kernel_composition_policy": "append-only-profile-extensions",
            "profile_composition_policy": "append-only",
            "input_hashes_locked": True,
            "source_values_unique": True,
        },
        "merge_policy": {
            "field_order": "kernel fields in source order, then profile-only fields in source order",
            "value_order": "kernel values first, then profile additions in source order",
            "deduplication": "stable first occurrence",
            "kernel_owner_preserved": True,
            "duplicate_field_profile_provenance_key": "extension_owner",
            "profile_only_metadata_preserved": True,
            "profile_cannot_remove_rename_or_redefine_kernel_values": True,
        },
        "serialization_policy": {
            "root_key_order": ROOT_KEY_ORDER,
            "duplicate_field_key_order": ["owner", "extension_owner", "values"],
            "indent_spaces": 2,
            "strings": "JSON quoted with ensure_ascii=false",
            "integers": "unquoted decimal",
            "null": "empty YAML scalar",
            "empty_list": "[]",
            "final_newline": True,
            "dynamic_fields": False,
        },
        "output": {
            "path": OUTPUT_PATH,
            "sha256": output_metrics["sha256"],
            "bytes": output_metrics["bytes"],
            "lines": output_metrics["lines"],
            "field_count": len(field_counts),
            "value_count": value_count,
            "field_value_counts": field_counts,
            "review_intervals_days_count": len(output["review_intervals_days"]),
            "volatility_defaults_count": len(output["volatility_defaults"]),
            "task_state_value_count": len(output["task_state"]["values"]),
            "frontmatter_extension_field_count": len(
                output["frontmatter_extensions"]["fields"]
            ),
        },
        "validation": {
            "kblib_parse": "PASS",
            "round_trip_equal": True,
            "check_vocab_broad": broad_check,
            "check_vocab_active_corpus": {
                "result": "no-fail-with-candidates",
                "aggregate": active_aggregate,
                "runs": active_checks,
            },
        },
    }
    receipt_file = root / args.receipt
    receipt_file.write_text(
        json.dumps(receipt, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )

    print(
        json.dumps(
            {
                "output": output_metrics,
                "field_count": len(field_counts),
                "value_count": value_count,
                "kblib_parse": "PASS",
                "check_vocab_broad_exit": broad_check["exit_code"],
                "check_vocab_broad_counts": broad_check["counts"],
                "check_vocab_active_aggregate": active_aggregate,
                "receipt": args.receipt,
            },
            ensure_ascii=False,
            sort_keys=True,
        )
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
